begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table organization_fixture(source uuid,mark uuid,result uuid,evidence uuid,item uuid,revision uuid,collection uuid);grant select,insert,update on organization_fixture to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','ef100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Organization course','School evidence','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','ef110000-0000-4000-8000-000000000001','ef100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Organized task','School task',10,'61000000-0000-4000-8000-000000000001');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);insert into organization_fixture(source)select internal.create_learning_submission('ef110000-0000-4000-8000-000000000001','School selected source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);update organization_fixture set mark=internal.mark_submission(source,0,'Native zero evidence',1,0,true);update organization_fixture set result=internal.release_marking(mark,1,true);
reset role;update organization_fixture fixture set evidence=(select released.evidence_id from app.result_revisions released where released.id=fixture.result);
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update organization_fixture set item=(internal.portfolio_command('create',null,jsonb_build_object('evidenceId',evidence,'sourceModel','numeric','title','School selected check','reflection','I explained the school check'),'organization-item',repeat('a',64),'organization')->>'id')::uuid;
reset role;update organization_fixture fixture set revision=(select current.revision_id from app.portfolio_current current where current.item_id=fixture.item);set local role cuevo_api;
update organization_fixture set collection=(internal.organize_portfolio('collection.create',null,'{"title":"School explanations","description":"My selected checking sources"}','organization-collection',repeat('b',64),'organization')->>'id')::uuid;
select lives_ok($$select internal.organize_portfolio('placement.create',(select item from organization_fixture),jsonb_build_object('collectionId',(select collection from organization_fixture),'expectedRevision',0,'position',2),'organization-placement',repeat('c',64),'organization')$$,'Learner organizes selected source without duplicating evidence');
select throws_ok($$select internal.organize_portfolio('placement.create',(select item from organization_fixture),' {"expectedRevision":1,"position":1}','organization-missing-collection',repeat('d',64),'organization')$$,'22023',null,'Missing collection choice is not unassignment');
select throws_ok($$select internal.organize_portfolio('placement.create',(select item from organization_fixture),' {"collectionId":false,"expectedRevision":1,"position":1}','organization-invalid-collection',repeat('d',64),'organization')$$,'22023',null,'Boolean collection choice fails explicit validation');
select is((internal.organize_portfolio('placement.create',(select item from organization_fixture),jsonb_build_object('collectionId',(select collection from organization_fixture),'expectedRevision',0,'position',2),'organization-placement',repeat('c',64),'organization')->>'revision')::integer,1,'Original placement key replays the single immutable revision');
select lives_ok($$select internal.organize_portfolio('feedback.request',(select item from organization_fixture),jsonb_build_object('revisionId',(select revision from organization_fixture),'expectedRevision',1,'message','Review this exact reflection','confirmRequest',true),'organization-request',repeat('e',64),'organization')$$,'Feedback request pins exact current reflection');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select is(jsonb_array_length(internal.read_portfolio_feedback_requests(25,null)->'items'),1,'Authorized teacher receives exact current feedback request');
select is(internal.read_portfolio_feedback_work((internal.read_portfolio_feedback_requests(25,null)->'items'->0->>'id')::uuid)->>'reflection','I explained the school check','Requested review includes the exact current reflection');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000005',true);
select is(jsonb_array_length(internal.read_portfolio_feedback_requests(25,null)->'items'),0,'Other teacher cannot retrieve the learner request');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.read_portfolio_organization(25,null,null)$$,'42501',null,'Parent cannot enumerate learner organization');
reset role;
update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select is(jsonb_array_length(internal.read_portfolio_feedback_requests(25,null)->'items'),0,'Current learner enrollment withdrawal hides pending teacher source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select is(jsonb_array_length(internal.read_portfolio_feedback_requests(25,null)->'items'),0,'Current learner enrollment withdrawal hides own pending source');reset role;
update app.enrollments set status='active'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
select is((select count(*)from app.portfolio_items where school_id='10000000-0000-4000-8000-000000000001'and id=(select item from organization_fixture)),1::bigint,'One selected evidence identity remains');
select throws_ok($$update app.portfolio_placement_revisions set position=9 where item_id=(select item from organization_fixture)$$,'55000',null,'Placement history immutable');
select ok(not has_table_privilege('cuevo_api','app.portfolio_feedback_requests','SELECT')and not has_function_privilege('authenticated','internal.organize_portfolio(text,uuid,jsonb,text,text,text)','EXECUTE'),'No raw browser organization or request grant');
-- Owner-only corruption/capacity fixture: source-free selected identities are unavailable and cannot silently exhaust collection scanning.
with new_items as(insert into app.portfolio_items(school_id,learner_id,source_model,evidence_id)select '10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','numeric',gen_random_uuid()from generate_series(1,1000)returning school_id,id,learner_id),new_revisions as(insert into app.portfolio_revisions(school_id,item_id,revision,title,reflection,created_by)select school_id,id,1,'Unavailable owner fixture','Source requires review',learner_id from new_items returning school_id,id,item_id),new_current as(insert into app.portfolio_current(school_id,item_id,revision_id)select school_id,item_id,id from new_revisions returning item_id)insert into app.portfolio_placement_revisions(school_id,item_id,learner_id,collection_id,revision,position)select new_items.school_id,new_items.id,new_items.learner_id,(select collection from organization_fixture),1,1 from new_items join new_current on new_current.item_id=new_items.id;
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select throws_ok($$select internal.read_portfolio_collection((select collection from organization_fixture),25,null)$$,'22023',null,'Exhausted inaccessible source scan requires review instead of false completion');
select*from finish();rollback;
